s+=r'''
if SIM:
    tg = {t['id']: t for t in W['targets']}
    print(plan(BASE, 4, 100, tg, 3)); sys.exit()

def log(*a): print(*a, flush=True)
def bearing(a, b): return math.degrees(math.atan2(b[1] - a[1], b[0] - a[0]))

def sim(x, y, hc, m, b):
    return drive(S, PH, x, y, hc + math.degrees(b), m, slip_base)

def predict_step(x, y, b, cmd):
    if cmd is None or cmd['action'] != 'drive': return x, y, 0.0 if cmd is None or cmd['action']=='wait' else R['sample_cost'], None
    r = sim(x, y, cmd['heading_deg'], cmd['metres'], b)
    return r['x'], r['y'], r['energy'], r

def lookahead(field, x, y, steps=2):
    n = nearest_free(x, y)
    if n not in field['N']: return field['pt']
    for _ in range(steps):
        nx_ = field['N'].get(n)
        if nx_ is None: return field['pt']
        n = nx_
    return cen(n % NX, n // NX)

def main():
    global eff
    with connect("http://lightlag:8000/mcp") as T:
        world = T.map()
        targets = {t['id']: t for t in world['targets']}
        est = list(BASE); b = 0.0
        P = [[0.01, 0, 0], [0, 0.01, 0], [0, 0, math.radians(2.9) ** 2]]
        k_est = 0; batt = 100.0
        cmds = {}
        done = set(); pending = {}
        tick = 0
        seq = []; need_plan = True; last_plan = -99
        last_exec = 0
        while True:
            nexec = max(tick + R['delay_ticks'] + 1, last_exec + 1)
            # predict to start of nexec
            x, y = est; B = batt
            for kk in range(k_est + 1, nexec):
                c = cmds.get(kk)
                x, y, e, _ = predict_step(x, y, b, c)
                B = min(100, B + solar(kk)) - 0.15 - e
            avail = {k: t for k, t in targets.items() if k not in done and k not in pending and t['appear_tick'] <= nexec}
            if need_plan or nexec - last_plan > 25:
                seq, ev = plan((x, y), nexec, B, avail, 1.0)
                log('PLAN', nexec, (round(x,1), round(y,1)), round(B,1), seq, ev)
                need_plan = False; last_plan = nexec
            seq = [k for k in seq if k in avail]
            fb = get_field('base', *BASE)
            wb, _ = leg(fb, x, y)
            if nexec + math.ceil(wb / 5 * 1.12) + 3 >= MAXT - 1:
                if seq: log('FORCE HOME', nexec)
                seq = []
            goal = seq[0] if seq else 'base'
            gp = BASE if goal == 'base' else (targets[goal]['x'], targets[goal]['y'])
            d = math.hypot(gp[0] - x, gp[1] - y)
            cmd = None
            if goal != 'base' and d < 0.8:
                cmd = {'action': 'sample'}
                pending[goal] = nexec; seq.pop(0)
            elif goal == 'base' and d < 1.2:
                cmd = {'action': 'wait'}
            elif B < 9:
                cmd = {'action': 'wait'}
            else:
                f = get_field(goal, *gp)
                final = d < 9
                aim = gp if final else lookahead(f, x, y, 2)
                if not final and math.hypot(aim[0]-x, aim[1]-y) < 6:
                    aim = lookahead(f, x, y, 3)
                br = bearing((x, y), aim)
                best = None
                for dh in range(-20, 21, 2):
                    hc = br + dh - math.degrees(b)
                    ms = [5.0]
                    if final:
                        ms = [min(5.0, max(0.25, d * q)) for q in (0.95, 1.0, 1.05, 1.1, 1.15, 1.2)]
                    for m in ms:
                        r = sim(x, y, hc, m, b)
                        if r['stop'] == 'tilt': continue
                        sx, sy = r['x'], r['y']
                        ii, jj = node_of(sx, sy)
                        pen = 0
                        if S.slope(sx, sy) > 0.3: pen += 50
                        if blocked[jj][ii] and not final: pen += 3
                        sc = math.hypot(aim[0] - sx, aim[1] - sy) + pen + 0.02 * abs(dh)
                        if best is None or sc < best[0]: best = (sc, hc, m)
                if best is None:
                    cmd = {'action': 'drive', 'heading_deg': (br + 180) % 360, 'metres': 2.0}
                else:
                    cmd = {'action': 'drive', 'heading_deg': round(best[1] % 360, 2), 'metres': round(best[2], 2)}
            try:
                ack = T.uplink([cmd])
            except ValueError as ex:
                log('REJECT', ex, cmd); ack = None
            if ack is not None:
                cmds[nexec] = cmd; last_exec = nexec
                if tick < 8: log('ACK', ack)
            out = T.advance(1)
            tick = out['current_tick']
            for p in out['packets']:
                k = p['tick']
                if k <= k_est: continue
                # predict
                c = cmds.get(k)
                for kk in range(k_est + 1, k):
                    est[0], est[1], _, _ = predict_step(est[0], est[1], b, cmds.get(kk))
                if c and c['action'] == 'drive':
                    r = sim(est[0], est[1], c['heading_deg'], c['metres'], b)
                    dx, dy = r['x'] - est[0], r['y'] - est[1]
                    if p['wheel_odometry'] > 0.01:
                        obs = p['visual_odometry'] / p['wheel_odometry']; mod = r['ground'] / max(1e-6, r['wheel'])
                        tn = p['terrain'] if p['terrain'] in slip_base else 'regolith'
                        lo, hi = PH['slip_base_ranges'][tn]
                        slip_base[tn] = min(hi, max(lo, slip_base[tn] + 0.08 * (mod - obs)))
                        if p['wheel_odometry'] < c['metres'] - 0.3:
                            sc_ = p['wheel_odometry'] / max(1e-6, r['wheel']); dx *= sc_; dy *= sc_
                    est[0] += dx; est[1] += dy
                    dd = math.hypot(dx, dy) + 1e-6
                    ux, uy = dx / dd, dy / dd
                    sa = (0.05 * dd) ** 2; sc2 = (dd * math.radians(1.5)) ** 2 + 0.01
                    Q = [[sa*ux*ux + sc2*uy*uy, (sa-sc2)*ux*uy, 0], [(sa-sc2)*ux*uy, sa*uy*uy + sc2*ux*ux, 0], [0, 0, math.radians(0.2)**2]]
                    Fm = [[1, 0, -dy], [0, 1, dx], [0, 0, 1]]
                    FP = [[sum(Fm[i][m] * P[m][j] for m in range(3)) for j in range(3)] for i in range(3)]
                    P = [[sum(FP[i][m] * Fm[j][m] for m in range(3)) + Q[i][j] for j in range(3)] for i in range(3)]
                k_est = k
                batt = p['battery']
                sn = math.sin(math.pi * k / MAXT)
                if sn > 0.15 and p['charge'] > 0 and batt < 99.5:
                    eff = 0.9 * eff + 0.1 * min(1.0, max(0.8, p['charge'] / (R['solar_peak'] * sn)))
                # update with position
                zx, zy = p['position']
                if 2 < zx < 598 and 2 < zy < 398:
                    Sm = [[P[0][0] + 1, P[0][1]], [P[1][0], P[1][1] + 1]]
                    det = Sm[0][0] * Sm[1][1] - Sm[0][1] * Sm[1][0]
                    Si = [[Sm[1][1] / det, -Sm[0][1] / det], [-Sm[1][0] / det, Sm[0][0] / det]]
                    K = [[sum(P[i][m] * Si[m][j] for m in range(2)) for j in range(2)] for i in range(3)]
                    rx, ry = zx - est[0], zy - est[1]
                    est[0] += K[0][0] * rx + K[0][1] * ry
                    est[1] += K[1][0] * rx + K[1][1] * ry
                    b += K[2][0] * rx + K[2][1] * ry
                    b = max(-math.radians(8), min(math.radians(8), b))
                    P = [[P[i][j] - sum(K[i][m] * P[m][j] for m in range(2)) for j in range(3)] for i in range(3)]
                st = set(p.get('sampled_targets') or [])
                for kid in list(pending):
                    if pending[kid] <= k:
                        if kid in st: done.add(kid); log('SAMPLED', kid, k)
                        else: log('SAMPLE FAILED', kid, k)
                        del pending[kid]; need_plan = True
                done |= st
                if p.get('events'):
                    log('EVENTS', k, p['events'])
                    if any('discover' in json.dumps(e) for e in p['events']):
                        world = T.map()
                        for t in world['targets']:
                            if t['id'] not in targets:
                                targets[t['id']] = t; log('NEW', t)
                        need_plan = True
                    if any(('tilt' in json.dumps(e)) or ('stop' in json.dumps(e)) for e in p['events']):
                        for kk in list(cmds):
                            if kk > k: del cmds[kk]
                        last_exec = max([kk for kk in cmds] + [tick + R['delay_ticks']])
                        need_plan = True
                if k % 10 == 0:
                    log('T', k, 'est', [round(v, 1) for v in est], 'gps', p['position'], 'b', round(math.degrees(b), 2),
                        'bat', round(batt, 1), 'eff', round(eff, 3), 'goal', seq[:2], {kk: round(v, 3) for kk, v in slip_base.items()}, 'P', round(P[0][0], 2))
            if out.get('episode_complete'):
                log('DONE', out); break
main()
'''
